package com.astrocare.service;
import com.astrocare.dto.*; import com.astrocare.entity.*; import com.astrocare.exception.*; import com.astrocare.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.messaging.simp.SimpMessagingTemplate; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class TelemetryService { private final VitalSignRepository vitals; private final AstronautRepository astronauts; private final SimpMessagingTemplate messaging;
 public TelemetryResponse latest(Long id,Authentication a){Astronaut astro=accessible(id,a);return vitals.findFirstByAstronautIdOrderByRecordedAtDesc(id).map(v->TelemetryResponse.from(v,true)).orElseThrow(()->new ResourceNotFoundException("No telemetry for astronaut "+id));}
 public List<TelemetryResponse> history(Long id,Authentication a,LocalDateTime from,LocalDateTime to){accessible(id,a);return vitals.findByAstronautIdAndRecordedAtBetweenOrderByRecordedAtAsc(id,from,to).stream().map(v->TelemetryResponse.from(v,false)).toList();}
 public TelemetryResponse simulate(SimulationRequest r){Astronaut a=astronauts.findById(r.astronautId()).orElseThrow(()->new ResourceNotFoundException("Astronaut not found"));int hr=a.getBaselineHeartRateBpm()==null?70:a.getBaselineHeartRateBpm();double spo=a.getBaselineSpo2Pct()==null?98:a.getBaselineSpo2Pct();int sys=a.getBaselineSystolicMmHg()==null?115:a.getBaselineSystolicMmHg();int dia=a.getBaselineDiastolicMmHg()==null?75:a.getBaselineDiastolicMmHg();int rr=a.getBaselineRespRateBpm()==null?15:a.getBaselineRespRateBpm();if(r.scenario()==SimulationRequest.Scenario.WARNING){hr+=25;spo-=2;rr+=5;}if(r.scenario()==SimulationRequest.Scenario.CRITICAL){hr+=65;spo-=8;sys+=35;rr+=12;}if(r.scenario()==SimulationRequest.Scenario.EVA_STRAIN){hr+=45;rr+=8;}VitalSign v=new VitalSign();v.setAstronaut(a);v.setRecordedAt(LocalDateTime.now(ZoneOffset.UTC));v.setHeartRateBpm(hr);v.setSpo2Pct(spo);v.setSystolicMmHg(sys);v.setDiastolicMmHg(dia);v.setCoreTempC(a.getBaselineCoreTempC()==null?36.8:a.getBaselineCoreTempC()+(r.scenario()==SimulationRequest.Scenario.CRITICAL?.6:r.scenario()==SimulationRequest.Scenario.EVA_STRAIN?.3:0));v.setRespRateBpm(rr);v.setSuitPressurePsi(r.scenario()==SimulationRequest.Scenario.EVA_STRAIN?4.3:null);v.setRadiationMsvH(.03);v.setSource(VitalSource.SIMULATED);VitalSign saved=vitals.save(v);TelemetryResponse out=TelemetryResponse.from(saved,false);messaging.convertAndSend("/topic/telemetry/"+a.getId(),out);return out;}
 private Astronaut accessible(Long id,Authentication auth){Astronaut a=astronauts.findById(id).orElseThrow(()->new ResourceNotFoundException("Astronaut not found"));if(auth.getAuthorities().stream().noneMatch(x->x.getAuthority().equals("ROLE_FLIGHT_SURGEON"))&&!a.getUser().getUsername().equals(auth.getName()))throw new ForbiddenOperationException("Astronauts may only view their own telemetry");return a;}
}
